// DUT Instantiation for Controller 1. CTRL1_GT_0 has LINK1_WIDTH lanes (X2 or
// X8, the CED's CTRL_LINK_WIDTH option; the Makefile reads it from defines.sv
// and passes it to tb_top as LINK1_WIDTH).
//
// Connects to this CED's own tb_top.sv, which declares scalar-suffixed
// vip2dut_1_p/n, dut2vip_1_p/n, refclk_1_p/n signals.
//
// Instantiates ctrl1_qdma_ep_sim_wrapper (generated by Vivado at
// launch_simulation time), NOT ctrl1_qdma_ep directly. Without the
// sim_wrapper's xlnoc instance and its hierarchical npp_in/npp_out
// cross-wiring into axi_noc2_0, the NoC Packet Protocol ports are left
// floating and the axi_noc2_0 NMU's own protection checker fires a hard
// Fatal at time ~19ns ("noc_valid on npp_in
// interface should not be unconnected / unknown").
// The sim_wrapper has the IDENTICAL external port list as ctrl1_qdma_ep
// (same 6 ports) since it only adds internal NoC wiring, so instantiating
// it in place of the bare BD wrapper is a drop-in swap -- no port changes.
//
// All C2H/H2C/tm_dsc_sts PL user logic lives inside the BD itself -- only
// the GT quad and its reference clock cross the BD boundary.

generate
  if (tb_top.LINK1_WIDTH != 0) begin : ctrl_inst
    ctrl1_qdma_ep_sim_wrapper dut_inst (
        .CTRL1_GT_0_grx_n        ( vip2dut_1_n[LINK1_WIDTH-1:0] ),
        .CTRL1_GT_0_grx_p        ( vip2dut_1_p[LINK1_WIDTH-1:0] ),
        .CTRL1_GT_0_gtx_n        ( dut2vip_1_n[LINK1_WIDTH-1:0] ),
        .CTRL1_GT_0_gtx_p        ( dut2vip_1_p[LINK1_WIDTH-1:0] ),

        .ctrl1_gt_refclk_0_clk_n ( refclk_1_n ),
        .ctrl1_gt_refclk_0_clk_p ( refclk_1_p )
    );
  end
endgenerate
